corrected_code:
router.post('/webhooks/plaid', express.json(), async (req, res) => {
  const plaidVerificationHeader = req.headers['plaid-verification'];
  const isPlaidValid = await verifyPlaidWebhook(plaidVerificationHeader, req.body);
  if (!isPlaidValid) return res.status(401).json({ error: 'Invalid Plaid JWT' });

  const { webhook_code, item_id, removed_transactions } = req.body;
  if (webhook_code === 'TRANSACTIONS_REMOVED' && removed_transactions?.length) {
    const bankConnection = await db.query('SELECT tenant_id FROM bank_connections WHERE plaid_item_id = $1', [item_id]);
    if (!bankConnection.rowCount) {
      return res.status(404).json({ error: 'Plaid item not recognized' });
    }
    const tenantId = bankConnection.rows[0].tenant_id;

    await db.query(
      'DELETE FROM cached_transactions WHERE transaction_id = ANY($1) AND tenant_id = $2',
      [removed_transactions, tenantId]
    );
  }
  res.json({ acknowledged: true });
});
